{
  "findings": [
    {
      "check_id": "CKV_AWS_260",
      "title": "Security Group allows ingress from all IPs",
      "resource": "aws_security_group.vault",
      "severity": "CRITICAL",
      "explanation": "The security group 'vault' allows ingress from 0.0.0.0/0, potentially exposing Vault to the entire internet."
    }
  ],
  "patched_code": "resource "aws_security_group" "vault" {
  name        = "vault"
  description = "Ingress for Vault"
  vpc_id      = aws_vpc.my_vpc.id
  dynamic "ingress" {
    iterator = port
    for_each = var.ingress_ports
    content {
      from_port   = port.value
      to_port     = port.value
      protocol    = "tcp"
      cidr_blocks = ["10.0.0.0/8"]
    }
  }
}",
  "fix_summary": "Restricted ingress CIDR blocks to a private IP range (10.0.0.0/8) to reduce exposure."
}
